"""Barrier-I collapse: the constant-term evaluation of a polynomial gcd witness."""

from __future__ import annotations

import math
from typing import List, Sequence, Tuple


def poly_eval(coeffs: Sequence[int], x: int) -> int:
    """Horner evaluation of f(x) for f given by ascending coefficients [c0, ..., cd]."""
    acc = 0
    for c in reversed(coeffs):
        acc = acc * x + c
    return acc


def witness_naive(coeffs: Sequence[int], N: int) -> int:
    """gcd(f(N), N), computed the expensive way: a full evaluation at N."""
    return math.gcd(poly_eval(coeffs, N), N)


def witness_collapsed(coeffs: Sequence[int], N: int) -> int:
    """gcd(f(0), N): the same value, by the Polynomial Barrier, at a fraction of the cost."""
    return math.gcd(coeffs[0] if coeffs else 0, N)


def prime_factors(n: int) -> List[int]:
    """Distinct primes dividing |n| (empty when n = 0), by trial division."""
    n, out, d = abs(n), [], 2
    if n == 0:
        return out
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            while n % d == 0:
                n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out.append(n)
    return out


def reveal_set(coeffs: Sequence[int]) -> List[int]:
    """The complete set of primes this invariant can ever expose, over all inputs."""
    return prime_factors(coeffs[0] if coeffs else 0)


def reveal_budget(coeffs: Sequence[int]) -> int:
    """The bound log2|f(0)| on the size of the reveal set."""
    c0 = abs(coeffs[0] if coeffs else 0)
    return int(math.log2(c0)) if c0 > 1 else 0


def analyse(coeffs: Sequence[int], N: int) -> Tuple[int, bool, List[int], int]:
    """Return (witness, splits, reveal set, reveal budget) for the invariant at N."""
    w = witness_collapsed(coeffs, N)
    assert w == witness_naive(coeffs, N), "the collapse identity is a theorem; it cannot fail"
    return w, 1 < w < N, reveal_set(coeffs), reveal_budget(coeffs)


if __name__ == "__main__":
    f = [6, 5, 1]  # x^2 + 5x + 6
    for N in (15, 35, 91, 50621):
        w, split, rev, bud = analyse(f, N)
        print(f"N = {N:<8} witness = {w:<5} split = {split!s:<6} reveal set = {rev} (budget {bud})")

"""Rigidity extraction: divide the factor polynomial out of an analytic device."""

from __future__ import annotations

import cmath
from typing import Callable, List, Tuple

Entire = Callable[[complex], complex]


def difference_quotient(F: Entire, a: complex, h: float = 1e-6) -> Entire:
    """
    The entire function G with F(z) = (z - a) G(z), assuming F(a) = 0.

    Away from a this is simply F(z)/(z - a); at z = a the singularity is removable
    and the value is F'(a), approximated here by a symmetric difference. Riemann's
    removable singularity theorem guarantees the result is again holomorphic.
    """

    def G(z: complex) -> complex:
        if abs(z - a) > h:
            return F(z) / (z - a)
        return (F(a + h) - F(a - h)) / (2 * h)

    return G


def extract_cofactor(F: Entire, p: complex, q: complex) -> Entire:
    """
    Given an entire device F vanishing at the two distinct points p and q, return the
    entire cofactor G with F(z) = (z - p)(z - q) G(z).

    Holomorphic rigidity says this G always exists; if the zero set of F is exactly
    {p, q} then G never vanishes off {p, q}, so the device carries no information
    beyond the factor polynomial (z - p)(z - q) = z^2 - (p+q) z + pq -- whose middle
    coefficient is the factorization itself.
    """
    return difference_quotient(difference_quotient(F, p), q)


def rigidity_report(
    F: Entire, p: complex, q: complex, probes: Tuple[complex, ...] = (0j, 10 + 5j, 150 + 0j)
) -> List[Tuple[complex, complex, float]]:
    """For each probe z, return (G(z), reconstruction (z-p)(z-q)G(z), |error| vs F(z))."""
    G = extract_cofactor(F, p, q)
    out: List[Tuple[complex, complex, float]] = []
    for z in probes:
        g = G(z)
        rebuilt = (z - p) * (z - q) * g
        out.append((g, rebuilt, abs(rebuilt - F(z))))
    return out


if __name__ == "__main__":
    p, q = 61, 97

    def device(z: complex) -> complex:
        return (z - p) * (z - q) * cmath.exp(z / 200.0)

    for g, rebuilt, err in rigidity_report(device, p, q):
        print(f"|G| = {abs(g):.6f}   reconstruction error = {err:.3e}   (G never vanishes)")
